///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_GoDsclInsert
 * @description Go Dscl Insert 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_GoDsclInsert = async function () {
    const sbmOptions = {
        id: "tx_fn_GoDsclInsert",
        method: "post",
        action: "/submission/searchDisclosureForm.do",
        ref: "dma_GoDsclInsertReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name tx_fn_Save
 * @description Save 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_Save = async function () {
    try { return await $c.data.downFile("/account/corporationReport.do", "", ($c.util.getComponent("dma_SaveReq") ? $c.util.getComponent("dma_SaveReq").getJSON() : {})); } catch (_e) { await $c.exception.handleError(_e, { context: '다운로드' }); return null; }
};

/**
 * @method
 * @name tx_fn_GoURL
 * @description Go URL 서버 호출
 * @param {*} action 제출 주소(호출부가 as-is form.action 으로 정하던 분기별 URL · 생략 시 기본 주소)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_GoURL = async function (action) {
    try { return await $c.data.downFile(action ?? "/account/corporationReport.do", "", ($c.util.getComponent("dma_GoURLReq") ? $c.util.getComponent("dma_GoURLReq").getJSON() : {})); } catch (_e) { await $c.exception.handleError(_e, { context: '다운로드' }); return null; }
};

