 * @hidden N
 */
scwin.goDsclInsert = async function () {
    await scwin.tx_fn_GoDsclInsert();
};

/**
 * @method
 * @name activeInput
 * @description active Input 처리
 * @param {*} _target _target
 * @returns {void}
 * @hidden N
 */
scwin.activeInput = function (_target) {
    const frm = $c.util.getComponent('corpForm');
    if (_target === 'corpTelNo') {
        if ((String($c.util.getComponent('ipt_corpTelNoCk').getValue() || "") !== "")) {
            $c.util.getComponent('ipt_corpTelNo1').readOnly = false;
            $c.util.getComponent('ipt_corpTelNo2').readOnly = false;
            $c.util.getComponent('ipt_corpTelNo3').readOnly = false;
        } else {
            $c.util.getComponent('ipt_corpTelNo1').readOnly = true;
            $c.util.getComponent('ipt_corpTelNo2').readOnly = true;
            $c.util.getComponent('ipt_corpTelNo3').readOnly = true;
        }
    } else {
        if (_target === 'headqtrFaxNo') {
            if ((String($c.util.getComponent('ipt_headqtrFaxNoCk').getValue() || "") !== "")) {
                $c.util.getComponent('ipt_headqtrFaxNo1').readOnly = false;
                $c.util.getComponent('ipt_headqtrFaxNo2').readOnly = false;
                $c.util.getComponent('ipt_headqtrFaxNo3').readOnly = false;
            } else {
                $c.util.getComponent('ipt_headqtrFaxNo1').readOnly = true;
                $c.util.getComponent('ipt_headqtrFaxNo2').readOnly = true;
                $c.util.getComponent('ipt_headqtrFaxNo3').readOnly = true;
            }
        } else {
            if (_target === 'hpage') {
                if ((String($c.util.getComponent('ipt_hpageCk').getValue() || "") !== "")) {
                    $c.util.getComponent('ipt_hpage').readOnly = false;
                } else {
                    $c.util.getComponent('ipt_hpage').readOnly = true;
                }
            } else {
                if (_target === 'empCnt') {
                    if ((String($c.util.getComponent('ipt_empCntCk').getValue() || "") !== "")) {
                        $c.util.getComponent('ipt_empCnt').readOnly = false;
                    } else {
                        $c.util.getComponent('ipt_empCnt').readOnly = true;
                    }
                } else {
                    if (_target === 'majProdNm') {
                        if ((String($c.util.getComponent('ipt_majProdNmCk').getValue() || "") !== "")) {
                            $c.util.getComponent('ipt_majProdNm').readOnly = false;
                        } else {
                            $c.util.getComponent('ipt_majProdNm').readOnly = true;
                        }
                    }
                }
            }
        }
    }
};

/**
 * @method
 * @name save
 * @description save 처리
 * @param {String} _flag _flag
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.save = async function (_flag) {
    const frm = $c.util.getComponent('corpForm');
    const isCorpTelNoCk = (String($c.util.getComponent('ipt_corpTelNoCk').getValue() || "") !== "");
    const isHeadqtrFaxNoCk = (String($c.util.getComponent('ipt_headqtrFaxNoCk').getValue() || "") !== "");
    const isHpageCk = (String($c.util.getComponent('ipt_hpageCk').getValue() || "") !== "");
    const isEmpCntCk = (String($c.util.getComponent('ipt_empCntCk').getValue() || "") !== "");
    const isMajProdNmCk = (String($c.util.getComponent('ipt_majProdNmCk').getValue() || "") !== "");
    if (!(isCorpTelNoCk || isHeadqtrFaxNoCk || isHpageCk || isEmpCntCk || isMajProdNmCk)) {
        await $c.win.alert('변경사항이 없습니다.');
        return;
    }
    if (isCorpTelNoCk) {
        if (await $c.fil.checkRequired($c.util.getComponent('ipt_corpTelNo1')) || await $c.fil.checkRequired($c.util.getComponent('ipt_corpTelNo2')) || await $c.fil.checkRequired($c.util.getComponent('ipt_corpTelNo3'))) {
            return;
        }
        if (!($c.fil.isNumberInput($c.util.getComponent('ipt_corpTelNo1')) && $c.fil.isNumberInput($c.util.getComponent('ipt_corpTelNo2')) && $c.fil.isNumberInput($c.util.getComponent('ipt_corpTelNo3')))) {
            await $c.win.alert('대표전화번호는 숫자만 입력하세요');
            return;
        }
        const corpTelNoVal = $c.util.getComponent('ipt_corpTelNo1').getValue()+ '-' + $c.util.getComponent('ipt_corpTelNo2').getValue()+ '-' + $c.util.getComponent('ipt_corpTelNo3').getValue();
        $c.util.getComponent('dma_GoDsclInsertReq').set('corpTelNo', corpTelNoVal);
    } else {
        $c.util.getComponent('dma_GoDsclInsertReq').set('corpTelNo', "");
    }
    if (isHeadqtrFaxNoCk) {
        if (await $c.fil.checkRequired($c.util.getComponent('ipt_headqtrFaxNo1')) || await $c.fil.checkRequired($c.util.getComponent('ipt_headqtrFaxNo2')) || await $c.fil.checkRequired($c.util.getComponent('ipt_headqtrFaxNo3'))) {
            return;
        }
        if (!($c.fil.isNumberInput($c.util.getComponent('ipt_headqtrFaxNo1')) && $c.fil.isNumberInput($c.util.getComponent('ipt_headqtrFaxNo2')) && $c.fil.isNumberInput($c.util.getComponent('ipt_headqtrFaxNo3')))) {
            await $c.win.alert('FAX는 숫자만 입력하세요');
            return;
        }
        const headqtrFaxNoVal = $c.util.getComponent('ipt_headqtrFaxNo1').getValue()+ '-' + $c.util.getComponent('ipt_headqtrFaxNo2').getValue()+ '-' + $c.util.getComponent('ipt_headqtrFaxNo3').getValue();
        $c.util.getComponent('dma_GoDsclInsertReq').set('headqtrFaxNo', headqtrFaxNoVal);
    } else {
        $c.util.getComponent('dma_GoDsclInsertReq').set('headqtrFaxNo', "");
    }
    if (isHpageCk) {
        if (await $c.fil.checkRequired($c.util.getComponent('ipt_hpage'))) {
            return;
        }
    } else {
        $c.util.getComponent("ipt_hpage").setValue("");
    }
    if (isEmpCntCk) {
        if (await $c.fil.checkRequired($c.util.getComponent('ipt_empCnt'))) {
            return;
        }
        if (!($c.fil.isNumberInput($c.util.getComponent('ipt_empCnt')))) {
            await $c.win.alert('종업원수 숫자만 입력하세요');
            return;
        }
    } else {
        $c.util.getComponent("ipt_empCnt").setValue("");
    }
    if (isMajProdNmCk) {
        if (await $c.fil.checkRequired($c.util.getComponent('ipt_majProdNm'))) {
            return;
        }
    } else {
        $c.util.getComponent("ipt_majProdNm").setValue("");
    }
    if (_flag === 'modify') {
        $c.util.getComponent('dma_GoDsclInsertReq').set('method', 'modifyCorporationReportModifyKosdaq');
    } else {
        $c.util.getComponent('dma_GoDsclInsertReq').set('method', 'modifyCorporationReport');
    }
    frm.action = 'corporationReport.do';
    await scwin.tx_fn_Save();
};

/**
 * @method
 * @name clear
 * @description clear 처리
 * @returns {void}
 * @hidden N
 */
scwin.clear = function () {
    $c.util.getComponent('dma_GoDsclInsertReq').reset();
    scwin.activeInput('corpTelNo');
    scwin.activeInput('headqtrFaxNo');
    scwin.activeInput('hpage');
    scwin.activeInput('empCnt');
    scwin.activeInput('majProdNm');
};

/**
 * @method
 * @name goURL
 * @description go URL 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.goURL = async function () {
    $c.util.getComponent('dma_GoDsclInsertReq').set('method', "searchCorporationReport");
    $c.util.getComponent('dma_GoDsclInsertReq').set('viewFlag', "");
    await scwin.tx_fn_GoURL("corporationReport.do");
};

/**
 * @method
 * @name initValue
 * @description init Value 처리
 * @param {*} _corpTelNo _corpTelNo
 * @param {*} _headqtrFaxNo _headqtrFaxNo
 * @param {*} _hpage _hpage
 * @param {*} _empCnt _empCnt
 * @param {String} _majProdNm _majProdNm
 * @returns {void}
 * @hidden N
 */
scwin.initValue = function (_corpTelNo, _headqtrFaxNo, _hpage, _empCnt, _majProdNm) {
    const frm = $c.util.getComponent('corpForm');
    if (_corpTelNo !== '') {
        $c.util.getComponent("ipt_corpTelNoCk").setValue(true);
        ((v) => { let cur = String(v ?? ""); for (let i = 3; i >= 1; i--) { const idx = cur.lastIndexOf("-"); const part = cur.substring(idx + 1); const c = $c.util.getComponent("corpTelNo" + i); if (c && c.setValue) { c.setValue(part); } cur = cur.substring(0, idx); } })(_corpTelNo);
    }
    if (_headqtrFaxNo !== '') {
        $c.util.getComponent("ipt_headqtrFaxNoCk").setValue(true);
        ((v) => { let cur = String(v ?? ""); for (let i = 3; i >= 1; i--) { const idx = cur.lastIndexOf("-"); const part = cur.substring(idx + 1); const c = $c.util.getComponent("headqtrFaxNo" + i); if (c && c.setValue) { c.setValue(part); } cur = cur.substring(0, idx); } })(_headqtrFaxNo);
    }
    if (_hpage !== '') {
        $c.util.getComponent("ipt_hpageCk").setValue(true);
        $c.util.getComponent("ipt_hpage").setValue(_hpage);
    }
    if (_empCnt !== '') {
        $c.util.getComponent("ipt_empCntCk").setValue(true);
        $c.util.getComponent("ipt_empCnt").setValue(_empCnt);
    }
    if (_majProdNm !== '') {
        $c.util.getComponent("ipt_majProdNmCk").setValue(true);
        $c.util.getComponent("ipt_majProdNm").setValue(_majProdNm);
    }
    scwin.activeInput('corpTelNo');
    scwin.activeInput('headqtrFaxNo');
    scwin.activeInput('hpage');
    scwin.activeInput('empCnt');
    scwin.activeInput('majProdNm');
};
